def apply_audit_tables(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        for model_name in ["AuditEvent", "DataSubjectRequest"]:
            schema_editor.create_model(apps.get_model("audit", model_name))

def reverse_audit_tables(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        for model_name in ["DataSubjectRequest", "AuditEvent"]:
            schema_editor.delete_model(apps.get_model("audit", model_name))

